CREATE TABLE ALLOCATION (ALLOCATIONID NUMBER(19) NOT NULL, ALLOCSTATUS VARCHAR2(255) NULL, ALLOCTYPE VARCHAR2(255) NULL, ALLOCATIONPRICE NUMBER(38) NULL, AVERAGEPRCGRPID NUMBER(19) NULL, AVERAGEPRICE NUMBER(38) NULL, CLEARINGMECHANISM VARCHAR2(255) NULL, CLIENTSSI NUMBER(19) NULL, COMMISSION NUMBER(38) NULL, COMMISSIONAMOUNT NUMBER(38) NULL, COMMISSIONTYPE VARCHAR2(255) NULL, EXCHANGEID NUMBER(19) NULL, FIRMDEPO NUMBER(19) NULL, INSTRUMENTID NUMBER(19) NULL, PAYMENTMETHOD VARCHAR2(255) NULL, QUANTITY NUMBER(38) NULL, SETTLEDATE NUMBER(10) NULL, SUBACCOUNTID NUMBER(19) NULL, TOPACCOUNTID NUMBER(19) NULL, TRADEDATE NUMBER(10) NULL, "VERSION" NUMBER(10) NULL, PRIMARY KEY (ALLOCATIONID))
CREATE TABLE AUDITRECORD (AUDITID NUMBER(19) NOT NULL, ACTOR VARCHAR2(255) NULL, DESCRIPTION VARCHAR2(255) NULL, ENTEREDDATETIME TIMESTAMP NULL, ISDELETED VARCHAR2(255) NULL, "OBJECT" CLOB NULL, OBJECTID NUMBER(38) NULL, OBJECTTYPE VARCHAR2(255) NULL, PRIMARY KEY (AUDITID))
CREATE TABLE AVERAGEPRICEGROUP (AVERAGEPRCGRPID NUMBER(19) NOT NULL, AVERAGEPRICE NUMBER(38) NULL, CAPACITY VARCHAR2(255) NULL, CLIENTID NUMBER(19) NULL, EXCHANGEID NUMBER(19) NULL, FLOWTYPE VARCHAR2(255) NULL, INSTRUMENTID NUMBER(19) NULL, MERGEKEY VARCHAR2(255) NULL, QUANTITY NUMBER(38) NULL, STATUS VARCHAR2(255) NULL, TRADEDATE NUMBER(10) NULL, "VERSION" NUMBER(10) NULL, PRIMARY KEY (AVERAGEPRCGRPID))
CREATE TABLE BACKOFFICENOTIFICATION (ID NUMBER(19) NOT NULL, TRADELEGID NUMBER(38) NULL, PRIMARY KEY (ID))
CREATE TABLE BLOCKCONFIRMATION (ID NUMBER(19) NOT NULL, ALLOCATIONID NUMBER(38) NULL, PRIMARY KEY (ID))
CREATE TABLE BULKCONF (BULKID NUMBER(19) NOT NULL, BULKTYPE VARCHAR2(255) NULL, CLIENTID NUMBER(38) NULL, CONFSTATUS VARCHAR2(255) NULL, EXCHANGEID NUMBER(38) NULL, EXECUTIONCOUNTRY VARCHAR2(255) NULL, EXECUTIONREGION VARCHAR2(255) NULL, "VERSION" NUMBER(38) NULL, PRIMARY KEY (BULKID))
CREATE TABLE CLIENTTRADE (CLIENTTRADEID NUMBER(19) NOT NULL, ALLOCATIONID NUMBER(38) NULL, BOOKINGSTATUS VARCHAR2(255) NULL, BOOKINGSUPPRESS VARCHAR2(255) NULL, CONFIRMSUPPRESS VARCHAR2(255) NULL, CONFSTATUS VARCHAR2(255) NULL, CTMSTATUS VARCHAR2(255) NULL, EXCHANGEID NUMBER(38) NULL, INSTRUMENTID NUMBER(38) NULL, QUANTITY NUMBER(38) NULL, SETTLEDATE NUMBER(38) NULL, TRADEDATE NUMBER(38) NULL, "VERSION" NUMBER(38) NULL, PRIMARY KEY (CLIENTTRADEID))
CREATE TABLE CONFIRMATION (CONFIRMATIONID NUMBER(19) NOT NULL, BULKID NUMBER(38) NULL, CLIENTTRADEID NUMBER(38) NULL, CONFSTATUS VARCHAR2(255) NULL, ISBULK NUMBER(38) NULL, "VERSION" NUMBER(38) NULL, PRIMARY KEY (CONFIRMATIONID))
CREATE TABLE CONTRACTNOTE (ID NUMBER(19) NOT NULL, CLIENTTRADEID NUMBER(38) NULL, PRIMARY KEY (ID))
CREATE TABLE FIGURATION (FIGURATIONID NUMBER(19) NOT NULL, COMMISSION NUMBER(38) NULL, COMMISSIONAMOUNT NUMBER(38) NULL, COMMISSIONTYPE NUMBER(38) NULL, ENTITYID NUMBER(38) NULL, ENTITYTYPE VARCHAR2(255) NULL, FEE1 NUMBER(38) NULL, FEE2 NUMBER(38) NULL, FEE3 NUMBER(38) NULL, FEE4 NUMBER(38) NULL, FEE5 NUMBER(38) NULL, FEE6 NUMBER(38) NULL, FEE7 NUMBER(38) NULL, FEE8 NUMBER(38) NULL, FEE9 NUMBER(38) NULL, LEVY NUMBER(38) NULL, NETPRICE NUMBER(38) NULL, NETPROCEED NUMBER(38) NULL, NETPROCESSFX NUMBER(38) NULL, PRICE NUMBER(38) NULL, PRINCIPAL NUMBER(38) NULL, QUANTITY NUMBER(38) NULL, TAX NUMBER(38) NULL, TRADEDATE NUMBER(38) NULL, PRIMARY KEY (FIGURATIONID))
CREATE TABLE FILL (FILLID NUMBER(19) NOT NULL, CAPACITY VARCHAR2(255) NULL, EXCHANGEID NUMBER(19) NULL, EXECUTEDSHARES NUMBER(38) NULL, EXECUTIONTIME TIMESTAMP NULL, EXTERNALREF VARCHAR2(255) NULL, INSTRUMENTID NUMBER(19) NULL, ISOFFMARKET VARCHAR2(255) NULL, ORDERID NUMBER(19) NULL, PRICE NUMBER(38) NULL, SIDE NUMBER(10) NULL, TRADEDATE NUMBER(10) NULL, "VERSION" NUMBER(10) NULL, PRIMARY KEY (FILLID))
CREATE TABLE ORDERS (ORDERID NUMBER(19) NOT NULL, AVERAGEPRCGRPID NUMBER(19) NULL, BOOKID NUMBER(19) NULL, CAPACITY VARCHAR2(255) NULL, CLIENTID NUMBER(19) NULL, COMMISSION NUMBER(38) NULL, COMMISSIONTYPE VARCHAR2(255) NULL, CURRENCY VARCHAR2(255) NULL, EXCHANGEID NUMBER(19) NULL, EXECUTIONCOUNTRY VARCHAR2(255) NULL, EXECUTIONREGION VARCHAR2(255) NULL, FLOWTYPE VARCHAR2(255) NULL, FOORDERREF VARCHAR2(255) NULL, FRONTOFFICECOMMENT NUMBER(38) NULL, FXDIRECTION VARCHAR2(255) NULL, FXRATE NUMBER(38) NULL, INSTRUMENTID NUMBER(19) NULL, MOCOMMENT VARCHAR2(255) NULL, ORDERSTATUS VARCHAR2(255) NULL, PORTFOLIOID NUMBER(19) NULL, QUANTITY NUMBER(38) NULL, SALESID VARCHAR2(255) NULL, SETTLECONVERSION VARCHAR2(255) NULL, SETTLECURRENCY VARCHAR2(255) NULL, SETTLEDATE NUMBER(10) NULL, SIDE VARCHAR2(255) NULL, TRADEDATE NUMBER(10) NULL, TRADERID VARCHAR2(255) NULL, "VERSION" NUMBER(10) NULL, PRIMARY KEY (ORDERID))
