CREATE TABLE TASK (TASKID NUMBER(19) NOT NULL, ASSIGNEDGROUP NUMBER(38) NULL, ASSIGNEDUSER NUMBER(38) NULL, COMMENTS VARCHAR2(255) NULL, CREATIONTIME TIMESTAMP NULL, DESCRIPTION VARCHAR2(255) NULL, MODIFIEDTIME TIMESTAMP NULL, OBJECTID NUMBER(38) NULL, OBJECTTYPE VARCHAR2(255) NULL, PRIORITY VARCHAR2(255) NULL, TASKSTATUS VARCHAR2(255) NULL, TASKTYPE VARCHAR2(255) NULL, TRADEDATE NUMBER(38) NULL, "VERSION" NUMBER(38) NULL, PRIMARY KEY (TASKID))
CREATE TABLE TRADELEG (TRADELEGID NUMBER(19) NOT NULL, ACCOUNTID NUMBER(38) NULL, AVERAGEPRCGRPID NUMBER(38) NULL, BOOKID NUMBER(38) NULL, CLIENTTRADEID NUMBER(38) NULL, ORDERID NUMBER(38) NULL, "TYPE" VARCHAR2(255) NULL, PRIMARY KEY (TRADELEGID))
